&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Dragon solaire adulte &lt;div style=&quot;float:right;&quot;&gt;FP 13&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Dragon&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Dragon.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Ciel&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Ciel.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Extraplanaire&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Extraplanaire.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Bestiaire 4 page 75&lt;/i&gt;
&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;25 600 PX&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Type-Dragon.html&quot; title=&quot;Dragon&quot;&gt;Dragon&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Feu.html&quot; title=&quot;Feu (sous-type)&quot;&gt;feu&lt;/a&gt;) de taille TG, LN&lt;/li&gt;&lt;li&gt;&lt;b&gt;Init &lt;/b&gt;+5 ; &lt;b&gt;Sens &lt;/b&gt;sens draconiques, vision dans les t&#233;n&#232;bres ; Perception +23&lt;/li&gt;&lt;li&gt;&lt;b&gt;Aura &lt;/b&gt;pr&#233;sence &#233;trang&#232;re (54 m, DD 23)&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;D&#233;fense&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;CA &lt;/b&gt;28, contact 9, pris au d&#233;pourvu 27 (Dex +1, naturelle +19, taille -2)&lt;/li&gt;&lt;li&gt;&lt;b&gt;pv &lt;/b&gt;212 (17d12+102)&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;f &lt;/b&gt;+13, &lt;b&gt;Vig &lt;/b&gt;+15, &lt;b&gt;Vol &lt;/b&gt;+15&lt;/li&gt;&lt;li&gt;&lt;b&gt;RD &lt;/b&gt;5/magie ; &lt;b&gt;Immunit&#233;s &lt;/b&gt;feu, paralysie, sommeil ; &lt;b&gt;RM &lt;/b&gt;24&lt;/li&gt;&lt;li&gt;&lt;b&gt;Faiblesse &lt;/b&gt;vuln&#233;rabilit&#233; au froid&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Attaque&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;VD &lt;/b&gt;15 m, vol 60 m (m&#233;diocre)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Corps &#224; corps&lt;/b&gt; morsure, +24 (2d8+13)&lt;ul&gt;&lt;li&gt;et 2 griffes, +24 (2d6+9)&lt;/li&gt;&lt;li&gt;et coup de queue, +22 (2d6+13)&lt;/li&gt;&lt;li&gt;et 2 ailes, +22 (1d8+4)&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Espace &lt;/b&gt;4,50 m ; &lt;b&gt;Allonge &lt;/b&gt;3 m (4,50 m avec la morsure)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; &#233;crasement, canalisation de vie (8/jour), feu primordial souffle (ligne de 30 m, 12d10 feu, DD 23)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Pouvoirs magiques&lt;/b&gt; (&lt;b&gt;NLS &lt;/b&gt;7 ; concentration +12)&lt;ul&gt;&lt;li&gt;&lt;i&gt;&#192; volont&#233;&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Coupe-De-Poussi&#232;re.html&quot; title=&quot;Coupe de poussi&#232;re&quot;&gt;coupe de poussi&#232;re&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Magie.html&quot; title=&quot;D&#233;tection de la magie&quot;&gt;d&#233;tection de la magie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re-Br&#251;lante.html&quot; title=&quot;Lumi&#232;re br&#251;lante&quot;&gt;lumi&#232;re br&#251;lante&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Sorts d’ensorceleur connus&lt;/b&gt; (&lt;b&gt;NLS &lt;/b&gt;7 ; concentration +12)&lt;ul&gt;&lt;li&gt;&lt;i&gt;3&#232;me (5/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Dissipation-De-La-Magie.html&quot; title=&quot;Dissipation de la magie&quot;&gt;dissipation de la magie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Don-Des-Langues.html&quot; title=&quot;Don des langues&quot;&gt;don des langues&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;2&#232;me (7/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Rayon-Ardent.html&quot; title=&quot;Rayon ardent&quot;&gt;rayon ardent&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;R&#233;sistance aux &#233;nergies destructives&quot;&gt;r&#233;sistance aux &#233;nergies destructives&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;1er (8/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Mage.html&quot; title=&quot;Armure de mage&quot;&gt;armure de mage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Bouclier.html&quot; title=&quot;Bouclier&quot;&gt;bouclier&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Charme-Personne.html&quot; title=&quot;Charme-personne&quot;&gt;charme-personne&lt;/a&gt; (DD 16), &lt;a class=&quot;pagelink&quot; href=&quot;Couleurs-Dansantes.html&quot; title=&quot;Couleurs dansantes&quot;&gt;couleurs dansantes&lt;/a&gt; (DD 16), &lt;a class=&quot;pagelink&quot; href=&quot;Projectile-Magique.html&quot; title=&quot;Projectile magique&quot;&gt;projectile magique&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;0 (&#224; volont&#233;)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Poison.html&quot; title=&quot;D&#233;tection du poison&quot;&gt;d&#233;tection du poison&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Illumination.html&quot; title=&quot;Illumination&quot;&gt;illumination&lt;/a&gt; (DD 15), &lt;a class=&quot;pagelink&quot; href=&quot;Lecture-De-La-Magie.html&quot; title=&quot;Lecture de la magie&quot;&gt;lecture de la magie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re.html&quot; title=&quot;Lumi&#232;re&quot;&gt;lumi&#232;re&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Manipulation-&#192;-Distance.html&quot; title=&quot;Manipulation &#224; distance&quot;&gt;manipulation &#224; distance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Prestidigitation.html&quot; title=&quot;Prestidigitation&quot;&gt;prestidigitation&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Saignement.html&quot; title=&quot;Saignement&quot;&gt;saignement&lt;/a&gt; (DD 15)&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Statistiques&lt;/div&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;For &lt;/b&gt;28, &lt;b&gt;Dex &lt;/b&gt;13, &lt;b&gt;Con &lt;/b&gt;20, &lt;b&gt;Int &lt;/b&gt;19, &lt;b&gt;Sag &lt;/b&gt;16, &lt;b&gt;Cha &lt;/b&gt;21&lt;/li&gt;&lt;li&gt;&lt;b&gt;BBA &lt;/b&gt;+17 ; &lt;b&gt;BMO &lt;/b&gt;+28 ; &lt;b&gt;DMD &lt;/b&gt;39 (43 contre croc-en-jambe)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dons &lt;/b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Puissance.html&quot; title=&quot;Attaque en puissance&quot;&gt;Attaque en puissance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-Multiples.html&quot; title=&quot;Attaques multiples&quot;&gt;Attaques multiples&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Canalisation-Rapide.html&quot; title=&quot;Canalisation rapide&quot;&gt;Canalisation rapide&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Canalisation-S&#233;lective.html&quot; title=&quot;Canalisation s&#233;lective&quot;&gt;Canalisation s&#233;lective&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Incantation-Silencieuse.html&quot; title=&quot;Incantation silencieuse&quot;&gt;Incantation silencieuse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;flexes-Surhumains.html&quot; title=&quot;R&#233;flexes surhumains&quot;&gt;R&#233;flexes surhumains&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Robustesse.html&quot; title=&quot;Robustesse&quot;&gt;Robustesse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l’initiative&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Volont&#233;-De-Fer.html&quot; title=&quot;Volont&#233; de fer&quot;&gt;Volont&#233; de fer&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (histoire, myst&#232;res, nature, plans, religion) +24, &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; +25, &lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt; +9, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +23, &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt; +21, &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; +23, &lt;a class=&quot;pagelink&quot; href=&quot;Vol.html&quot; title=&quot;Vol&quot;&gt;Vol&lt;/a&gt; +13&lt;/li&gt;&lt;li&gt;&lt;b&gt;Langues &lt;/b&gt;a&#233;rien, c&#233;leste, commun, draconique, ign&#233;, sylvestre, terreux&lt;/li&gt;&lt;li&gt;&lt;b&gt;Particularit&#233;s &lt;/b&gt;ne respire pas, vol stellaire&lt;br /&gt;&lt;/div&gt;&lt;br /&gt;&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;ul style=&quot;margin: 0 0 -10 0;margin-top: 6px;margin-bottom: 12px;&quot;&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Sid&#233;ral.html&quot; title=&quot;Les dragons sid&#233;raux&quot;&gt;dragons sid&#233;raux&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Solaire.html&quot; title=&quot;Dragon sid&#233;ral solaire&quot;&gt;dragons solaires&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;/ul&gt;&lt;i&gt;Ce majestueux dragon brille comme le soleil. Ses ailes polies luisent de couleurs flamboyantes et une couronne de cornes orne sa t&#234;te.&lt;/i&gt;  &lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;Arrogants et fiers, les dragons solaires se consid&#232;rent comme les g&#233;niteurs de la lumi&#232;re et de la vie dans l’immensit&#233; de l’espace. Ils consid&#232;rent toutes les cr&#233;atures vivantes comme leurs propres cr&#233;ations.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
